import asyncio,json
from pathlib import Path
from playwright.async_api import async_playwright,expect
D=Path("/tmp/browser/clinical-qa")
D.mkdir(parents=True,exist_ok=True)
async def main():
 async with async_playwright() as p:
  b=await p.chromium.launch(headless=True);out=[]
  for width,height,label in [(1280,1800,'desktop'),(390,844,'mobile')]:
   c=await b.new_context(viewport={'width':width,'height':height});page=await c.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.on('dialog',lambda d:d.accept())
   await page.goto('http://localhost:8080/capture',wait_until='networkidle');await page.get_by_role('button',name='Enter manually').click()
   for name,val in zip(['CK.R','CKH.R','CRT.MA','CFF.MA','CK.LY30'],[3,4,80,40,2.8]):await page.get_by_role('spinbutton',name=name,exact=True).fill(str(val))
   await page.get_by_role('checkbox',name='Adult patient').check();await page.get_by_role('checkbox',name='Original TEG').check();await page.get_by_role('radio',name='Active significant bleeding').check();await page.get_by_role('checkbox',name='I verified').check();await page.get_by_role('button',name='View interpretation',exact=True).click();await expect(page.get_by_text('No configured threshold crossed',exact=False)).to_be_visible();await expect(page.get_by_text('CK.R: 3 min — low',exact=False)).to_be_visible();await expect(page.get_by_text('CRT.MA: 80 mm — high',exact=False)).to_be_visible();await page.screenshot(path=str(D/f'{label}-abnormal-no-trigger.png'));out.append(f'{label}: high MA/short R flagged despite no trigger; no anticoagulation advice')
   await page.get_by_role('link',name='Edit values').click();await page.get_by_role('radio',name='Trauma',exact=True).check();await page.get_by_role('radio',name='Unknown',exact=True).first.check();await page.get_by_role('radio',name='Active significant bleeding').check();await page.get_by_role('checkbox',name='I verified').check();await page.get_by_role('button',name='View interpretation',exact=True).click();await expect(page.get_by_text('Timing or bleeding indication is not established',exact=False)).to_be_visible();await page.go_back();await expect(page.get_by_role('heading',name='Confirm values')).to_be_visible();out.append(f'{label}: unknown trauma timing, browser back preserves case')
   await page.goto('http://localhost:8080/algorithm',wait_until='networkidle');await expect(page.locator('.mermaid-host svg')).to_have_count(3);await page.get_by_placeholder('Search by keyword').fill('combined deficits');await expect(page.get_by_text('1 rule and 1 source match.')).to_be_visible();await page.get_by_role('heading',name='Reduced clot strength').screenshot(path=str(D/f'{label}-matched-rule.png'));await page.get_by_placeholder('Search by keyword').scroll_into_view_if_needed();await page.screenshot(path=str(D/f'{label}-search-evidence.png'));out.append(f'{label}: matching reference panel screenshot and diagrams render without page overflow')
   await page.goto('http://localhost:8080/capture',wait_until='networkidle');await page.evaluate("Storage.prototype.setItem=function(){throw Error('blocked')};Storage.prototype.removeItem=function(){throw Error('blocked')};Storage.prototype.getItem=function(){throw Error('blocked')};void 0");await page.get_by_role('button',name='Enter manually').click();await page.get_by_role('spinbutton',name='CK.R',exact=True).fill('6');await expect(page.get_by_role('alert')).to_contain_text('Browser storage is unavailable');await page.get_by_role('button',name='Discard and start over').click();await page.get_by_role('button',name='Enter manually').click();await expect(page.get_by_role('spinbutton',name='CK.R',exact=True)).to_have_value('');await expect(page.get_by_role('checkbox',name='Adult patient')).not_to_be_checked();await page.get_by_role('alert').screenshot(path=str(D/f'{label}-storage-warning.png'));out.append(f'{label}: blocked storage warns, memory fallback and explicit reset work')
   assert not errors,errors;await c.close()
  await b.close();D.joinpath('extra-results.json').write_text(json.dumps(out,indent=2));print('\n'.join(out))
asyncio.run(main())
